use vstd::prelude::*;

verus! {

    /// Rotates a non‐empty vector of u32 to the right by n positions.
    ///
    /// If `len = list.len()` and `k = n % len` and `s = len - k`,
    /// then the result is
    ///   list[s..len] ++ list[0..s]
    ///
    /// We prove by a loop‐invariant that
    ///   new_list[j] == list[(s + j) % len]   for all j < count,
    /// and in the end count = len.
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0,
        ensures
            new_list.len() == list.len(),
        ensures
            forall |i: usize| i < list.len() ==>
                new_list[i] == list[(i + list.len() - n % list.len()) % list.len()],
    {
        let len: usize = list.len();
        // rotation amount modulo length
        let k: usize = n % len;
        // starting index of suffix
        let s: usize = len - k;
        // build the rotated vector
        let mut new_list: Vec<u32> = Vec::with_capacity(len);
        let mut count: usize = 0;
        while count < len
            invariant
                count <= len,
                new_list.len() == count,
                // for all processed positions j < count, we already have
                // new_list[j] == list[(s + j) % len]
                forall |j: usize| j < count ==>
                    new_list[j] == list[(s + j) % len],
            decreases
                len - count,
        {
            let idx: usize = (s + count) % len;
            new_list.push(list[idx]);
            count += 1;
        }
        new_list
    }

}

fn main() {
    // Example usage (not verified by Verus):
    let v = vec![10u32, 20, 30, 40];
    let r = rotate_right(&v, 1);
    // r should be [40,10,20,30]
    println!("{:?}", r);
}